changeSet.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM "Exercises" AS exercise
        WHERE NOT EXISTS (
            SELECT 1 FROM "ExerciseTranslations" AS translation
            WHERE translation."ExerciseId" = exercise."Id" AND translation."Culture" = 'en')
    ) THEN
        RAISE EXCEPTION 'Some exercises have no instructions in the staging data';
    END IF;
END $$;

ALTER TABLE "Exercises" ADD CONSTRAINT "CK_Exercises_MainMuscle"
    CHECK ("MainMuscle" IN ('Back', 'Biceps', 'Chest', 'Core', 'Legs', 'Shoulders', 'Triceps'));
ALTER TABLE "Exercises" ADD CONSTRAINT "CK_Exercises_Equipment"
    CHECK ("Equipment" IN ('Barbell', 'Bench', 'Bodyweight', 'Cable', 'Dumbbells', 'Machine'));
ALTER TABLE "Exercises" ADD CONSTRAINT "CK_Exercises_Difficulty"
    CHECK ("Difficulty" IN ('Beginner', 'Intermediate', 'Advanced'));
ALTER TABLE "Exercises" ADD CONSTRAINT "CK_Exercises_MovementPattern"
    CHECK ("MovementPattern" IN ('Push', 'Pull', 'Squat', 'Hinge', 'Carry', 'Core', 'Isolation'));
ALTER TABLE "ExerciseSecondaryMuscles" ADD CONSTRAINT "CK_ExerciseSecondaryMuscles_Muscle"
    CHECK ("Muscle" IN ('Back', 'Biceps', 'Brachialis', 'Calves', 'Chest', 'Core', 'Forearms', 'FrontDeltoids', 'Glutes', 'Hamstrings', 'HipAbductors', 'HipFlexors', 'InnerThighs', 'Lats', 'LongHeadOfBiceps', 'LongHeadOfTriceps', 'LowerAbs', 'LowerBack', 'LowerChest', 'LowerLats', 'MedialDeltoids', 'MiddleTrapezius', 'Obliques', 'Quadriceps', 'RearDeltoids', 'RectusAbdominis', 'Rhomboids', 'RotatorCuff', 'Shoulders', 'TeresMajor', 'Traps', 'Triceps', 'UpperChest', 'UpperTrapezius'));

rollback.sql:
ALTER TABLE "ExerciseSecondaryMuscles" DROP CONSTRAINT "CK_ExerciseSecondaryMuscles_Muscle";
ALTER TABLE "Exercises" DROP CONSTRAINT "CK_Exercises_MovementPattern";
ALTER TABLE "Exercises" DROP CONSTRAINT "CK_Exercises_Difficulty";
ALTER TABLE "Exercises" DROP CONSTRAINT "CK_Exercises_Equipment";
ALTER TABLE "Exercises" DROP CONSTRAINT "CK_Exercises_MainMuscle";
ALTER TABLE "Exercises" ALTER COLUMN "Difficulty" DROP NOT NULL;
ALTER TABLE "Exercises" ALTER COLUMN "Equipment" DROP NOT NULL;
